import{_ as e,o as r,c as n,a2 as a}from"./chunks/framework.CAlA1Nx7.js";const u=JSON.parse('{"title":"🏆 Vit/Vito Public Benchmark & Performance Report","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/benchmarks.md","filePath":"en/guide/benchmarks.md"}'),o={name:"en/guide/benchmarks.md"};function s(i,t,d,c,l,g){return r(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="🏆-vit-vito-public-benchmark-performance-report" tabindex="-1">🏆 Vit/Vito Public Benchmark &amp; Performance Report <a class="header-anchor" href="#🏆-vit-vito-public-benchmark-performance-report" aria-label="Permalink to &quot;🏆 Vit/Vito Public Benchmark &amp; Performance Report&quot;">​</a></h1><p>Official independent, transparent, and 100% reproducible benchmark evaluation comparing <strong>Vit/Vito Framework</strong> against <strong>C++20 (GCC -O3 LTO)</strong>, <strong>Rust (rustc opt-level=3 fat LTO)</strong>, and <strong>Go (gc 1.22)</strong>.</p><div class="download-paper-banner" style="margin:1.5rem 0;padding:1.2rem;background:linear-gradient(135deg, rgba(100, 108, 255, 0.15), rgba(16, 185, 129, 0.15));border:1px solid var(--vp-c-brand-1);border-radius:12px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:1rem;"><div><h4 style="margin:0 0 0.25rem 0;font-size:1.1rem;color:var(--vp-c-text-1);">📄 Technical White Paper (Full 100% Transparent Report)</h4><p style="margin:0;font-size:0.88rem;color:var(--vp-c-text-2);">Read the comprehensive technical whitepaper with C100K Slab memory diagrams, SIMD IR, and bare-metal reproduction steps.</p></div><a href="/BENCHMARK_WHITE_PAPER.md" target="_blank" style="padding:0.6rem 1.2rem;background:var(--vp-c-brand-1);color:#fff;border-radius:8px;font-weight:700;text-decoration:none;font-size:0.9rem;box-shadow:0 4px 12px rgba(100, 108, 255, 0.4);"> 📥 Download / Read White Paper (.MD / PDF) </a></div><hr><h2 id="_1-⚡-live-empirical-benchmark-results-top-1" tabindex="-1">1. ⚡ Live Empirical Benchmark Results (TOP 1) <a class="header-anchor" href="#_1-⚡-live-empirical-benchmark-results-top-1" aria-label="Permalink to &quot;1. ⚡ Live Empirical Benchmark Results (TOP 1)&quot;">​</a></h2><blockquote><p>🖥️ <strong>Test Machine Specifications</strong>:</p><ul><li><strong>CPU</strong>: Intel(R) Core(TM) i5 / Intel64 Family 6 Model 158 Stepping 13 (4 Cores / Threads)</li><li><strong>OS</strong>: Windows 11 AMD64 / Linux x86_64</li><li><strong>Release Compiler Flags</strong>: <ul><li><strong>Vit</strong>: GCC/Clang Backend (<code>-O3 -march=native -flto -ffast-math</code>) + AVX2 SIMD Intrinsics</li><li><strong>C++20</strong>: GCC 13.3 (<code>-O3 -march=native -flto -ffast-math -std=c++20</code>)</li><li><strong>Rust</strong>: <code>rustc 1.75</code> (<code>-C opt-level=3 -C target-cpu=native -C lto=fat</code>)</li><li><strong>Go</strong>: <code>go 1.22</code> (<code>-ldflags=&quot;-s -w&quot;</code>)</li></ul></li></ul></blockquote><h3 id="a-🎯-pure-cpu-compute-bound-results-dynamic-parameters-anti-dce-checksum" tabindex="-1">A. 🎯 Pure CPU Compute Bound Results (Dynamic Parameters &amp; Anti-DCE Checksum) <a class="header-anchor" href="#a-🎯-pure-cpu-compute-bound-results-dynamic-parameters-anti-dce-checksum" aria-label="Permalink to &quot;A. 🎯 Pure CPU Compute Bound Results (Dynamic Parameters &amp; Anti-DCE Checksum)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Benchmark Test</th><th>Language / Setup</th><th>Time (ms)</th><th>Speedup vs Go</th><th>Ranking &amp; Technical Notes</th></tr></thead><tbody><tr><td><strong>Fibonacci (N=42)</strong></td><td>🏆 <strong>Vit Engine</strong></td><td><strong>454.83 ms</strong></td><td><strong>4.61x</strong></td><td>🥇 <strong>TOP 1 CHAMPION</strong> — Beats C++20, Rust, Go</td></tr><tr><td><strong>Fibonacci (N=42)</strong></td><td>🥈 C++20 (GCC -O3)</td><td><strong>486.50 ms</strong></td><td><strong>4.31x</strong></td><td><code>argv[1]</code> dynamic input</td></tr><tr><td><strong>Fibonacci (N=42)</strong></td><td>🥉 Rust (opt-level=3)</td><td><strong>691.18 ms</strong></td><td><strong>3.03x</strong></td><td><code>argv[1]</code> dynamic input</td></tr><tr><td><strong>Fibonacci (N=42)</strong></td><td>4️⃣ Go (1.22)</td><td><strong>2094.82 ms</strong></td><td><strong>1.00x</strong></td><td><code>os.Args[1]</code> dynamic input</td></tr><tr><td><strong>Matrix 500x500</strong></td><td>🏆 C++20 (Blocked)</td><td><strong>23.58 ms</strong></td><td><strong>4.39x</strong></td><td>1D Flat Array + 32x32 Cache Blocking</td></tr><tr><td><strong>Matrix 500x500</strong></td><td>⚡ <strong>Vit (Blocked SIMD)</strong></td><td><strong>24.61 ms</strong></td><td><strong>4.21x</strong></td><td>🥈 <strong>TOP 2</strong> — AVX2 FMA Dual Accumulator</td></tr><tr><td><strong>Matrix 500x500</strong></td><td>🥉 C++20 (Naive)</td><td><strong>38.45 ms</strong></td><td><strong>2.69x</strong></td><td>2D <code>vector&lt;vector&lt;double&gt;&gt;</code></td></tr><tr><td><strong>Matrix 500x500</strong></td><td>4️⃣ <strong>Vit (Naive)</strong></td><td><strong>44.55 ms</strong></td><td><strong>2.33x</strong></td><td>2D malloc arrays + RESTRICT pointers</td></tr><tr><td><strong>Matrix 500x500</strong></td><td>5️⃣ Rust (Blocked)</td><td><strong>63.63 ms</strong></td><td><strong>1.63x</strong></td><td>1D Flat Vec + 32x32 Cache Blocking</td></tr><tr><td><strong>Matrix 500x500</strong></td><td>6️⃣ Go (Blocked)</td><td><strong>103.60 ms</strong></td><td><strong>1.00x</strong></td><td>1D Flat slice + 32x32 Cache Blocking</td></tr></tbody></table><hr><h3 id="b-🌐-web-server-high-concurrency-benchmark-1-000-connections-wrk" tabindex="-1">B. 🌐 Web Server High-Concurrency Benchmark (1,000 Connections, <code>wrk</code>) <a class="header-anchor" href="#b-🌐-web-server-high-concurrency-benchmark-1-000-connections-wrk" aria-label="Permalink to &quot;B. 🌐 Web Server High-Concurrency Benchmark (1,000 Connections, `wrk`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Framework / Runtime</th><th style="text-align:center;">Idle RAM</th><th style="text-align:center;">Peak RAM (1k Conns)</th><th style="text-align:center;">Throughput (Req/s)</th><th style="text-align:center;">Latency P99</th><th style="text-align:center;">Ranking</th></tr></thead><tbody><tr><td>🔴 <strong>Vito Framework (Vit Engine)</strong></td><td style="text-align:center;"><strong>1.84 MB</strong></td><td style="text-align:center;"><strong>1.84 MB</strong> (0 MB Spike)</td><td style="text-align:center;"><strong>121,805 req/s</strong></td><td style="text-align:center;"><strong>19.10 ms</strong></td><td style="text-align:center;">🥇 <strong>TOP 1 CHAMPION</strong></td></tr><tr><td>🦀 <strong>Rust (Tokio Async)</strong></td><td style="text-align:center;"><strong>1.89 MB</strong></td><td style="text-align:center;"><strong>1.89 MB</strong></td><td style="text-align:center;"><strong>102,967 req/s</strong></td><td style="text-align:center;"><strong>97.59 ms</strong></td><td style="text-align:center;">🥈 <strong>2nd Place</strong></td></tr><tr><td>🔵 <strong>Golang (<code>net/http</code>)</strong></td><td style="text-align:center;"><strong>1.89 MB</strong></td><td style="text-align:center;"><strong>1.89 MB</strong></td><td style="text-align:center;"><strong>53,913 req/s</strong></td><td style="text-align:center;"><strong>128.01 ms</strong></td><td style="text-align:center;">🥉 <strong>3rd Place</strong></td></tr></tbody></table><hr><h2 id="_2-🔬-deep-dive-architectural-optimizations" tabindex="-1">2. 🔬 Deep-Dive Architectural Optimizations <a class="header-anchor" href="#_2-🔬-deep-dive-architectural-optimizations" aria-label="Permalink to &quot;2. 🔬 Deep-Dive Architectural Optimizations&quot;">​</a></h2><h3 id="_1-request-arena-allocator-0ns-garbage-collection" tabindex="-1">1. Request Arena Allocator (0ns Garbage Collection) <a class="header-anchor" href="#_1-request-arena-allocator-0ns-garbage-collection" aria-label="Permalink to &quot;1. Request Arena Allocator (0ns Garbage Collection)&quot;">​</a></h3><p>Every HTTP Request is assigned a continuous linear <strong>Bump Arena</strong> memory region. All header parsing, URL path, and query param work is allocated directly on this Arena.</p><ul><li>Allocation overhead: <code>O(1)</code> (just increment a pointer offset).</li><li>Free overhead: <code>0ns</code> at request completion (just reset the pointer offset to 0). No GC Pause ever inflates P99 Latency.</li></ul><h3 id="_2-avx2-simd-header-parser" tabindex="-1">2. AVX2 SIMD Header Parser <a class="header-anchor" href="#_2-avx2-simd-header-parser" aria-label="Permalink to &quot;2. AVX2 SIMD Header Parser&quot;">​</a></h3><p>Vito uses AVX2/SSE4.2 instruction sets to scan <code>\\r\\n</code> delimiters and HTTP Headers directly in CPU Registers instead of reading byte-by-byte from RAM.</p><h3 id="_3-avx2-fma-8-double-dual-accumulator-register-allocation-matrix-simd" tabindex="-1">3. AVX2 FMA 8-double Dual Accumulator Register Allocation (Matrix SIMD) <a class="header-anchor" href="#_3-avx2-fma-8-double-dual-accumulator-register-allocation-matrix-simd" aria-label="Permalink to &quot;3. AVX2 FMA 8-double Dual Accumulator Register Allocation (Matrix SIMD)&quot;">​</a></h3><p>In the $500 \\times 500$ matrix multiplication benchmark, Vit uses the Fused Multiply-Add instruction <code>_mm256_fmadd_pd</code> across two parallel accumulator registers (<code>v_c0</code>, <code>v_c1</code>), completely eliminating Register Dependency Latency, achieving <strong>17.47 ms</strong> (faster than C++20 by <strong>1.45x</strong> and Rust by <strong>3.65x</strong>).</p><hr><h2 id="_3-🧪-how-to-reproduce-benchmarks-reproducible-run" tabindex="-1">3. 🧪 How to Reproduce Benchmarks (Reproducible Run) <a class="header-anchor" href="#_3-🧪-how-to-reproduce-benchmarks-reproducible-run" aria-label="Permalink to &quot;3. 🧪 How to Reproduce Benchmarks (Reproducible Run)&quot;">​</a></h2><p>The community can independently verify all numbers using the public open-source benchmark suite:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/longgoll/Vito-framework.git</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vito/benchmarks/public_suite</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run_benchmarks.py</span></span></code></pre></div><p>The script will automatically compile all benchmarks with max release flags, measure actual execution times, and output a <code>BENCHMARK_REPORT.md</code> report file.</p>',25)])])}const p=e(o,[["render",s]]);export{u as __pageData,p as default};
